-- 193_replace_decision_145_2021_public_and_private_offering_of_bonds_rules_consolidated_text_stored_as_two_rows_with_reversed_ligatures_and_no_preamble.sql
--
-- إعادة هيكلة قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (145) لسنة 2021 بشأن ضوابط وإجراءات الطرح العام والخاص للسندات، بالنص الموحد "وفقا لأخر تعديل بتاريخ 2026/7/8"
-- (تعديل بقرار مجلس إدارة الهيئة رقم 136 بتاريخ 2026/7/8) كما نشرته الهيئة على موقعها.
--
-- ===== الحالة السابقة (الهجرة 022 وما بعدها) =====
-- مخزَّن بصفين (article_no = 1 و2، article_suffix_order = -1، إجمالى 14107 حروف) بلا ديباجة ولا عناوين ولا hierarchical_location، وكل صف نسخة من الطبقة النصية للـPDF مباشرة:
--   * الصف (1، -1) يجمع مادة الإصدار الأولى والهامش 1 وكل ضوابط الطرح من "أولاً" إلى "ثامناً" فى نص واحد، والصف (2، -1) مادة النشر وحدها؛
--   * وصلات الحروف مقلوبة فى الطبقة النصية: "واإلجارءات" و"الم ارفقة" و"قارارت" و"االكتتاب" و"اإلفصاح" و"اعتباارً" و"األشخاص" بدل صيغها الصحيحة، فلا يجد البحث النصى الكلمات الصحيحة؛
--   * عناوين الضوابط الثمانية بحروف مشوهة ومفككة ("ا" منفصلة على سطر قبل "أول : أنواع الطروحات :" وقبل "ثانيا" و"ثالثا: املستثمر املؤهل للطرح اخلاص")، وعلامة الهامش "(2)" على سطر مستقل، وهوامش أسفل الصفحات (1–4) مختلطة بالمتن، وأرقام بنود القوائم والفواصل CRLF؛
--   * سقوط ديباجة القرار كلها (الاطلاعات السبعة وموافقة المجلس بتاريخ 2021/9/29) وعنوان القرار وعبارة "وفقا لأخر تعديل".
-- (هذه أبرز العيوب لا حصرها؛ أُعيدت كتابة المتن كله من الأصل ولم يُعتمد على المخزَّن أساساً.)
--
-- ===== المصدر والمنهجية =====
-- PDF الهيئة الموحد (9 صفحات، مُنتَج بـ Word بطبقة نصية بوصلات حروف مقلوبة وخط عناوين بلا طبقة سليمة). نُقل النص كاملاً من الصفحات بصرياً (200 dpi، كل صفحة فى ثلاثة أشرطة) ثم قوبل
-- بالطبقة النصية (مفاتيح الحروف المرتبة لكل كلمة فلا تؤثر فيها الوصلات المقلوبة، ومطابقة الألف المقصورة والياء، ومطابقة الأرقام) وبمخرجات OCR مستقلة (tesseract ara)؛ فلم يبق فرق
-- غير المعروف منها: شظايا الترويسة والتذييل، وتمطيط الحروف فى الطبقة النصية، و"ليادة" مكان "زيادة" فى بند المؤسسات المالية. أُبقى إملاء الأصل وأخطاؤه كما هى: "وفقا لأخر تعديل" و"وفقا لأخر قوائم مالية معتمدة"
-- و"الافصاح" (البند 2 من بيانات المصدر فى سابعاً) و"ثلاثين يوم عمل" و"على أن يرفق بها مراقب الحسابات من المقيدين" (بلا كلمة "تقرير" فى الأصل) و"فى" بالألف المقصورة فى بعض المواضع.
-- حُذفت ترويسة الصفحات وتذييلها وأرقامها وسطر "رئيس الهيئة" وسطر "مجلس إدارة الهيئة العامة للرقابة المالية" وكلمة "قرر" (لا توقيع مطبوع فى الأصل). الأرقام لاتينية، وأُسقطت علامات التشكيل الصغيرة وأُبقى تنوين الفتح
-- مكتوباً على الحرف قبل الألف كباقى الهجرات.
--
-- ===== تعديلات التمثيل (معلنة) =====
--   * عنوان كل ضابط (أولاً .. ثامناً) صار حقل title للصف بالترتيب العربى المطبوع مع شرطة ("أولاً - أنواع الطروحات")، ولم يُبقَ فى المتن؛ علامات الهامش على العناوين (2) و(3) نُقلت إلى العنوان،
--     وعلامة الهامش 4 المطبوعة فى آخر البند 2 من (ج) فى سادساً بقيت فى متنه "(4)"؛ وعلامة (1) إلى hierarchical_location للديباجة مع عنوان القرار وعبارة "النص الموحد".
--   * قوائم البنود كلها بأرقام "N-" لاتينية، كل بند فى سطر، والبنود المحروفة "(أ) (ب) (ج)" كما طُبعت. قائمتا ثالثاً (الأشخاص ذوو الملاءة المالية: 1–3، والمؤسسات المالية: 1–20) تحت سطر تعريف
--     كل منهما، ثم الفقرة الأخيرة "وأي شركات أو جهات أخرى..." كما فى الأصل. وفى رابعاً قائمتان (1–5 ثم 1–4 بعد فقرة "ومع عدم الإخلال بالبيانات والمستندات")، وفى سابعاً "البيانات الخاصة بالمصدر" و"البيانات الخاصة بالإصدار"
--     بسطر عنوان لكل قائمة دون النقطة المطبوعة قبله.
--   * النسب المئوية بلا مسافة "(0.5%)" و"(1%)" و"(10%)" و"(5%)"، والرمز "(BBB-)" بترتيبه المنطقى (مطبوع بصرياً "(–BBB)").
--   * الهامش 2 (نص المادة 4 مكرراً من قانون سوق رأس المال) مع الفقرتين المقتبستين وسطر النقاط المطبوع "...........". وأُدخلت الهوامش الأربعة فى القسم 9 دون حذف.
--
-- ===== الهيكل =====
-- 12 صفاً، 12 نسخة (version_no = 1): ديباجة (article_no = 0)، مادتا الإصدار (1 و2 بـarticle_suffix_order = -1، وهما المفتاحان المخزَّنان نفسيهما فلا تعيد بذرة القرار إدراج الصفين القديمين:
-- إدراج laws فيها ON CONFLICT DO NOTHING وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود)، ثم ضوابط "أولاً" إلى "ثامناً" كمواد المرفق (article_no = 1..8، article_suffix_order = 0 على اصطلاح المنصة
-- فى الهجرة 022 لمواد الإصدار المشاركة أرقام مواد القواعد المرفقة)، ثم القسم 9 "هوامش التعديلات اللاحقة" (الهوامش 1–4).
--
-- ===== التاريخ والنسخ (قرار تقديرى يُراجَع) =====
-- النص المتاح هو الموحد بعد تعديل 2026/7/8 فقط؛ لا نص أصلى لعام 2021 ولا تاريخ نشر بالوقائع المصرية فى المصدر (المادة 2 تُعمل القرار من اليوم التالى لنشره). فجُعل effective_from = 2026-07-08
-- (تاريخ آخر تعديل المذكور فى المصدر) للنسخ الاثنتى عشرة، وسُجِّل amended_by = 136/2026 مع change_note على الضابطين خامساً (الفقرة الثانية من البند 1 والبند 3) وسادساً (البند 2 من (ج)) وحدهما،
-- وهما اللذان استبدلهما قرار 136/2026 بحسب الهامشين 3 و4. أثر ذلك: لا نسخة للقرار قبل 2026-07-08 فى الاستعلام بالتاريخ (فجوة معلنة بدل نص معدَّل منسوب لتواريخ سابقة)، كما فى الهجرات 138 و154 و155 و192.
-- لاحقاً: رفع نص 2021 الأصلى وقرار 136/2026 لبناء النسخة التاريخية. لا تُمس بيانات laws.
--
-- ===== ملاحظة للمراجعة القانونية (لا يعالجها هذا الملف) =====
-- ديباجة 145/2021 تُحيل إلى القرار 48/2019 (ضوابط وإجراءات الطرح العام والخاص) ولا ينص المتن المرفوع على إلغائه؛ فمصير 48/2019 يُراجَع فى هجرة laws المؤجلة.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (12 صفاً بديباجة سليمة والقسم 9 موجود)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف
-- (عدد، لفظ مغاير للأصل، بقايا وصلات مقلوبة أو ترويسة أو علامات هوامش مختلطة، محتوى المواد، تاريخ سريان الأفرع، إجمالى الطول 14223 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix193$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[193] القرار 145/2021 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 12
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[193] القرار 145/2021 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[193] أُزيلت % مادة من القرار 145/2021 (صفان مخزنان بوصلات حروف مقلوبة وبلا ديباجة، والمادة الأولى تبتلع الضوابط المرفقة وهوامش الصفحات وعناوين الضوابط مشوهة)', v_n;
  END IF;
END
$fix193$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (145) لسنة 2021 بشأن ضوابط وإجراءات الطرح العام والخاص للسندات (النص الموحد وفقاً لآخر تعديل بتاريخ 2026/7/8) (1)$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم (159) لسنة 1981 ولائحته التنفيذية؛
وعلى قانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992 ولائحته التنفيذية؛
وعلى القانون رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية؛
وعلى قرار مجلس إدارة الهيئة رقم (11) لسنة 2014 بشأن قواعد قيد وشطب الأوراق المالية بالبورصة المصرية؛
وعلى قرار مجلس إدارة الهيئة رقم (23) لسنة 2016 بشأن قواعد إصدار السندات وصكوك التمويل غير الحاصلة على تصنيف ائتماني وقواعد الاكتتاب فيها وضوابط قيدها بالبورصة المصرية؛
وعلى قرار مجلس إدارة الهيئة رقم (172) لسنة 2018 بشأن قواعد وإجراءات إصدار وطرح السندات قصيرة الأجل؛
وعلى قرار مجلس إدارة الهيئة رقم (48) لسنة 2019 بشأن ضوابط وإجراءات الطرح العام والخاص؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2021/9/29؛$b0_0$
  FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins0_0;

