  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, $h1$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h1$, $t1_0$أولاً - أنواع الطروحات (2)$t1_0$, $b1_0$1- الطرح العام: يتم الطرح العام للسندات بعرض الشركة أو الجهة المصدرة للسندات على أشخاص طبيعيين أو اعتباريين غير محددين سلفًا.
