WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, $h2$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h2$, $t2_0$ثانياً - أطراف عملية طرح السندات$t2_0$, $b2_0$1- الشركة أو الجهة المصدرة (المصدر).
