WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, $h3$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h3$, $t3_0$ثالثاً - المستثمر المؤهل للطرح الخاص$t3_0$, $b3_0$يقصد بالمستثمر المؤهل للطرح الخاص، الأشخاص ذوو الملاءة المالية والمؤسسات المالية، وذلك على النحو الآتي:
الأشخاص ذوو الملاءة المالية، ويقصد بهم:
1- الأشخاص الطبيعية ذوو الخبرة التي لا تقل عن ثلاث سنوات في مجال الائتمان وإدارة الأموال والاستثمار فيها أو إدارة الصناديق والعمل لدى أي بنك أو شركة تأمين أو مؤسسة مالية مصرية أو أجنبية.
2- الأشخاص الطبيعية المالكة لأوراق مالية أو أدوات دين مالية تزيد قيمتها على خمسمائة ألف جنيه في شركتين مساهمتين مصريتين على الأقل بخلاف الشركة المصدرة.
3- الشركات التي لا يقل رأسمالها المدفوع عن مليون جنيه مصري.
المؤسسات المالية، ويقصد بهم:
1- البنوك المصرية وفروع البنوك الأجنبية الخاضعة لإشراف البنك المركزي المصري.
2- شركات التأمين أو إعادة التأمين.
3- الشركات التي يكون غرضها الاشتراك في تأسيس الشركات التي تصدر أوراقًا مالية أو زيادة رؤوس أموالها (بنوك الاستثمار).
4- الشركات والجهات التي تزاول نشاط البورصات.
5- شركات الوساطة في السندات والمتعاملون الرئيسيون.
6- شركات رأس المال المخاطر.
7- شركات المقاصة والإيداع والقيد المركزي.
8- شركات التمويل العقاري أو إعادة التمويل العقاري.
9- شركات التأجير التمويلي أو التخصيم.
10- شركات التمويل الاستهلاكي.
11- شركات تمويل المشروعات المتوسطة والصغيرة و/أو متناهية الصغر.
12- صناديق الاستثمار.
13- شركات الاستثمار المباشر.
14- البنوك الأجنبية، والشركات والجهات العاملة في الأنشطة المالية غير المصرفية بالخارج، شريطة أن تكون خاضعة لإشراف ورقابة جهة تمارس اختصاصات مثيلة للبنك المركزي أو الهيئة بحسب الأحوال.
15- المؤسسات المالية العربية والإقليمية والدولية.
16- الهيئة القومية للبريد.
17- صناديق التأمين الخاصة التي تبلغ حجم أموالها المستثمرة أكثر من 100 مليون جنيه.
18- جهاز تنمية المشروعات المتوسطة والصغيرة ومتناهية الصغر.
19- صندوق مصر السيادي للاستثمار والتنمية.
20- صندوق مصر الفرعي للخدمات المالية والتحول الرقمي.
وأي شركات أو جهات أخرى من الأشخاص الاعتبارية العامة والخاصة صادر بشأنها قرار من مجلس إدارة الهيئة.$b3_0$
  FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
