WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, $h4$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h4$, $t4_0$رابعاً - ضوابط طرح السندات$t4_0$, $b4_0$1- يجب ألا تقل القيمة الاسمية للسند الواحد عن مائة جنيه مصري أو ما يعادلها بالعملة الأجنبية.
2- يكون الإصدار بالجنيه المصري، ويجوز أن يكون بالعملة الأجنبية إذا كانت للمصدر إيرادات بالعملة الأجنبية تكفي لسداد مستحقات حملة السندات في مواعيد استحقاقها.
3- يجب أن تودع السندات لدى شركة الإيداع والقيد المركزي للأوراق المالية، ويتم تسويتها وفقًا للقواعد المطبقة في هذا الشأن.
4- يجوز قيد السندات في البورصة المصرية وفقًا لأحكام المادة (12) من قواعد قيد وشطب الأوراق المالية بالبورصة المصرية وتسري في هذه الحالة أحكام الباب الثالث من تلك القواعد الخاص بمتطلبات الإفصاح، على أن يكون القيد قبل تاريخ توزيع أول كوبون.
وفى حالة عدم قيد السندات بالبورصة المصرية فيقتصر التداول عليها بين المستثمرين المؤهلين.
5- يجوز إعادة شراء أو السداد المعجل للسندات قبل تاريخ استحقاقها وفقًا للضوابط الموضحة بمذكرة المعلومات، مع إيضاح أي تعويضات قد تستحق للمكتتبين كتعويض نظير ذلك في كل حالة.
ومع عدم الإخلال بالبيانات والمستندات التي يجب على المصدر موافاة الهيئة بها وفقًا للمادة (7) من اللائحة التنفيذية لقانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992، يلتزم المصدر بموافاة الهيئة بما يلي:
1- ملخص للتدفقات النقدية له ومصادرها ونسب السيولة والربحية والهيكل المالي أو أي نسب أخرى تطلبها الهيئة وتقرير مراقب الحسابات عن التوقعات المستقبلية وفقًا لمعايير المراجعة المصرية.
2- بيان من شركة الإيداع والقيد المركزي للأوراق المالية بمدى التزامه بسداد مستحقات حملة السندات في مواعيد استحقاقها وذلك في حال وجود إصدارات سابقة له.
3- شهادة تصنيف ائتماني صادرة من إحدى جهات التصنيف الائتماني المعتمدة لدى الهيئة شريطة ألا تقل عن درجة (BBB-) أو ما يعادلها، وذلك في الحالات التي تتطلب ذلك وفقًا للمادة (34) من اللائحة التنفيذية لقانون سوق رأس المال.
4- أي بيانات أو مستندات أخرى ترى الهيئة ضرورة موافاتها بها.$b4_0$
  FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
