WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, $h5$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h5$, $t5_0$خامساً - ضوابط الاكتتاب في السندات من خلال طرح خاص (3)$t5_0$, $b5_0$1- يكون الحد الأدنى للاكتتاب بالنسبة للمستثمرين الأفراد ذوي الملاءة بنسبة (0.5%) من قيمة الطرح أو مليون جنيه أيهما أقل، وبالنسبة للمؤسسات المالية نسبة (1%) من قيمة الطرح أو 10 ملايين جنيه أيهما أقل.
وفي حالة السندات المقيدة بالبورصة المصرية يجب أن تخصص شريحة بنسبة لا تقل عن (10%) من إجمالي السندات المطروحة لأشخاص طبيعية أو اعتبارية -بخلاف المكتتبين في الشريحة الأولى -ولا تتقيد هذه الأشخاص عند اكتتابهم في النسبة المذكورة بالحد الأدنى للاكتتاب المشار إليه.
2- إذا تم طرح السندات في طرح عام وطرح خاص فلا يجوز للمكتتبين في الطرح الخاص الاكتتاب في الشريحة المخصصة للطرح العام للسندات، مع مراعاة غلق باب الاكتتاب للطرح العام والطرح الخاص في ذات اليوم.
3- يتم تحديد فترة الاكتتاب للطرح الخاص وفقًا لما يراه المصدر على ألا تقل فترة الاكتتاب عن أسبوع ولا تجاوز ثلاثين يوم عمل، ويجوز غلق باب الاكتتاب في حالة تغطية الطرح بالكامل قبل انتهاء مدة الاكتتاب المحددة، وإذا لم يتم الاكتتاب في جميع السندات المطروحة خلال المدة المحددة، جاز بموافقة الهيئة مد فترة الاكتتاب لمدد أخرى بعد التأكد من عدم تأثر درجة التصنيف الائتماني الممنوحة للجهة المصدرة و/أو محفظة التوريق المحالة بحسب الأحوال.$b5_0$
  FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
