SELECT id, 1, body, '2026-07-08', 'active', 136, 2026, $c5_0$النص الموحد: استبدال نص الفقرة الثانية من البند (1) ونص البند (3) من (خامساً) بقرار مجلس إدارة الهيئة رقم (136) بتاريخ 2026/7/8$c5_0$ FROM ins5_0;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, $h6$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h6$, $t6_0$سادساً - التزامات أطراف عملية الطرح$t6_0$, $b6_0$يجب أن تتناول مذكرة المعلومات إقرار وتعهد من شركة ترويج وتغطية الاكتتاب بأنها المسئولة عن القيام بأعمال الترويج الخاصة بهذا الطرح، وببذل عناية الرجل الحريص فى هذا الشأن، كما يجب أن يوضح ما إذا كانت الشركة، مدير للطرح فقط أم مدير للطرح ومتعهد للتغطية وضامن للاكتتاب.
ومع عدم الإخلال بأي التزامات على أطراف عملية طرح السندات وفقًا لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم (159) لسنة 1981 ولائحته التنفيذية وقانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992 ولائحته التنفيذية وقرارات مجلس إدارة الهيئة الصادرة في هذا الشأن، تكون التزامات أطراف عملية الطرح على النحو الآتي:
(أ) التزامات جهات ترويج وتغطية وضمان الاكتتاب:
1- التعاقد مع المصدر على أن يتضمن التعاقد التزاماته ومسئولياته وآليات وإجراءات عمله وإخطار الهيئة بصورة من هذا الاتفاق.
2- الاكتتاب في السندات التي لم يتم تغطيتها في حالة التعهد بتغطية وضمان الاكتتاب.
3- الإفصاح عن عملية الطرح ونتائج الاكتتاب وفقًا للقواعد والإجراءات السارية في هذا الشأن.
4- عدم الإدلاء بأية معلومات غير صحيحة عن عملية الطرح ونتائج الاكتتاب.
(ب) التزامات مدير الطرح:
1- التحقق والإثبات والاحتفاظ بالسجلات والمستندات المؤيدة لها، وذلك على النحو الآتي:
(أ) بيان الملاءة المالية لعملاء الطرح الخاص واستيفائهم للتعريف والمواصفات الواردة بمذكرة المعلومات.
(ب) سلامة واكتمال كافة بيانات الأوامر وصفة وشخصية الموقع على الأمر.
(ج) بيان الأشخاص والشركات والجهات التي تم توجيه إخطار لها بغرض الاكتتاب في الطرح الخاص.
2- الإفصاح عن أية معلومات جوهرية طارئة أو جديدة من شأنها التغيير في أية بيانات وردت بمذكرة المعلومات وردت إليه أو تمكن من الاطلاع عليها.
3- تحديد الفئة المستهدفة من المستثمرين مع المصدر ونسبة وطريقة التخصيص للأفراد والمؤسسات مع مراعاة البند (1) من خامسًا من هذه الضوابط.
4- إخطار المصدر بكافة قواعد الطرح الخاص وأية متطلبات قانونية وإجرائية متعلقة بالطرح.
(ج) التزامات المستشار القانوني للطرح:
1- الإفصاح بمذكرة المعلومات وإقراره بصحة البيانات والمعلومات التي تضمنتها مذكرة المعلومات فيما يخص التأكد من التزامات المصدر والقضايا والتراخيص الخاصة به وأي بنود أخرى هامة للمستثمرين المرتقبين.
2- إعداد مذكرة المعلومات وفقًا للقوانين والقواعد المنظمة لإصدار السندات مرفقًا بها المستندات المؤيدة، وكذا الالتزام في حالة سندات التوريق بتقديم إقرار يتضمن صحة وسلامة العقود والضمانات المرتبطة محل محفظة التوريق، وأن المحفظة لم يسبق حوالتها أو التنازل عنها للغير وأنها لم تستخدم كضمان لأي تمويل ممنوح للجهة المحيلة وأنها خالية من أي حقوق للغير قد تؤثر سلبًا على حقوق حملة السندات، وذلك كله وقت نفاذ الحوالة، ودون الإخلال بالتزامات المستشار القانوني على النحو المنصوص عليه بالمادة (304) من اللائحة التنفيذية لقانون سوق رأس المال (4)
(د) التزامات الشركة أو الجهة المصدرة للسندات:
تلتزم الشركة أو الجهة المصدرة على الأقل بما يلي:
1- أنها المسئولة عن صحة كافة البيانات والمستندات والإقرارات المقدمة للهيئة وكذلك البيانات والمعلومات الواردة بمذكرة المعلومات، وإقرارها بعدم إغفالها وكافة الأطراف المرتبطة بعملية طرح السندات لأي بيانات أو معلومات أخرى يكون لها تأثير على قرار المستثمر بالاكتتاب في السندات من عدمه.
2- اتخاذ الإجراءات المقررة قانونًا وفقًا لأحكام قانون سوق رأس المال ولائحته التنفيذية في حالة تغيير أي بند من بنود مذكرة المعلومات وعلى الأخص الحصول على موافقة الهيئة وجماعة حملة السندات.
3- موافاة الهيئة بكافة التقارير والمستندات المفصح عنها بمذكرة المعلومات طوال عمر السندات.
4- الالتزام بكافة التعهدات والإقرارات المفصح عنها بمذكرة المعلومات.$b6_0$
  FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, amended_by_law_no, amended_by_law_year, change_note)
SELECT id, 1, body, '2026-07-08', 'active', 136, 2026, $c6_0$النص الموحد: استبدال البند (2) من (ج - التزامات المستشار القانوني للطرح) من (سادساً) بقرار مجلس إدارة الهيئة رقم (136) بتاريخ 2026/7/8$c6_0$ FROM ins6_0;

WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, $h7$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h7$, $t7_0$سابعاً - المعلومات والبيانات التي يتعين توافرها بمذكرة المعلومات$t7_0$, $b7_0$يجب أن تتضمن مذكرة المعلومات البيانات والمعلومات الكافية عن الإصدار وعلى الأخص ما يلي:
البيانات الخاصة بالمصدر:
1- الإفصاح عن الشكل القانوني وغرض الشركة ورأس المال المرخص به والمصدر والمدفوع.
2- الافصاح عن بيان المساهمات في رأس المال المالكين لنسبة (5%) فأكثر من رأس مال الشركة، وبيان أعضاء مجلس الإدارة.
3- الإفصاح عن التأمينات على أصول المصدر، والرهونات والامتيازات الحالية المترتبة على تلك الأصول، والموقف الضريبي للمصدر.
4- الإفصاح عن قيمة صافي أصول المصدر وفقا لأخر قوائم مالية معتمدة.
5- الإفصاح عن أهم القضايا أو الدعاوى المرفوعة ضد المصدر والتي يكون لها تأثير على الهيكل التمويلي له والمخصصات المحددة لمواجهة تلك القضايا في حالة تحديدها.
البيانات الخاصة بالإصدار:
1- قرار الجمعية العامة للشركة المصدرة بالموافقة على الإصدار وقرار مجلس إدارة الشركة في حالة تفويضه من قبل الجمعية العامة بإصدار الشروط التفصيلية الخاصة بالإصدار. وبالنسبة للجهات المصدرة من غير الشركات قرار السلطة المختصة بها بالموافقة على الإصدار.
2- الإفصاح عن شروط الإصدار بما في ذلك القيمة الإجمالية للإصدار وعدد وعمر السندات والاستهلاك ومواعيد سداده ومرتبة السندات من حيث الأولوية في السداد في حالة إفلاس الشركة المصدرة وسعر العائد وأسلوب احتسابه ومواعيد صرفه.
3- الإفصاح عن شهادة التصنيف الائتماني للمصدر و/أو السندات المصدرة.
4- الإفصاح عن الغرض من الإصدار وأوجه استخدام حصيلة السندات.
5- الإفصاح عن قواعد السداد المعجل للسندات مع إيضاح أي تعويضات قد تستحق لحملة السندات كتعويض نظير ذلك.
6- الإفصاح عن الضمانات أو التأمينات لصالح حملة السندات.
7- الإفصاح عن كافة المخاطر المتعلقة بالمصدر والإصدار وطرق التحوط أو التخفيف من تلك المخاطر.
8- الإفصاح عن موقف قيد السندات بالإيداع والقيد المركزي وبالبورصة المصرية.
9- الإفصاح عن بيانات الاكتتاب الخاصة بالسندات ومنها الجهة متلقية الاكتتاب، والحد الأدنى والأقصى للاكتتاب، وتاريخ فتح وغلق باب الاكتتاب، وطريقة التخصيص ورد المستحقات.
10- الإفصاح عن البيانات المالية للمصدر والتي تشمل:
(أ) القوائم المالية له وفقًا لمعايير المحاسبة المصرية عن السنوات الثلاثة السابقة أو عن مدة التأسيس أيهما أقل على أن يرفق بها مراقب الحسابات من المقيدين بسجل الهيئة ومعد وفقا لمعايير المراجعة المصرية.
(ب) ملخص لتدفقاته النقدية ومصادرها ونسب السيولة والربحية والهيكل المالي أو أي نسب أخرى تطلبها الهيئة وتقرير مراقب الحسابات عن التوقعات المستقبلية وفقًا لمعايير المراجعة المصرية.
11- تعهدات وإقرارات المصدر طوال عمر السندات، وحالات الإخلال والإجراءات المتخذة في حالة حدوثها.
ويجب أن تتضمن مذكرة المعلومات الخاصة بسندات التوريق المعلومات والبيانات المشار إليها بهذه الضوابط بما يتوافق مع التنظيم القانوني وطبيعة هذا النوع من السندات، وذلك دون الإخلال بأي معلومات أو بيانات أخرى يجب استيفائها وفقًا لأحكام اللائحة التنفيذية لقانون سوق رأس المال.$b7_0$
  FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins7_0;

WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, $h8$ضوابط وإجراءات الطرح العام والخاص للسندات (المرفقة بقرار مجلس إدارة الهيئة رقم (145) لسنة 2021)$h8$, $t8_0$ثامناً - متطلبات الإفصاح الواجب الالتزام به طوال عمر السندات$t8_0$, $b8_0$مع عدم الإخلال بأي التزامات يتعين على المصدر الالتزام بالإفصاح عنها وفقًا لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم (159) لسنة 1981 ولائحته التنفيذية وقانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992 ولائحته التنفيذية، يتعين على المصدر موافاة الهيئة وجماعة حملة السندات طوال عمر السندات على الأقل بما يلي:
1- نسخة من القوائم المالية السنوية خلال 90 يومًا على الأكثر من انتهاء السنة المالية على أن تكون القوائم معدة وفقًا لمعايير المحاسبة المصرية ومرفقًا بها تقرير مراقب الحسابات عنها المعد وفقًا لمعايير المراجعة المصرية.
2- نسخة من القوائم المالية ربع السنوية خلال 45 يومًا على الأكثر من انتهاء كل ربع سنة مالية على أن تكون القوائم معدة وفقًا لمعايير المحاسبة المصرية ومرفقًا بها تقرير مراقب الحسابات عنها المعد وفقًا لمعايير المراجعة المصرية.
3- كتاب من مراقب الحسابات يوضح كافة النسب المالية المحددة بمذكرة المعلومات ويوضح مدى التزام المصدر بها، على أن يرفق هذا الكتاب بالقوائم المالية السنوية وربع السنوية للمصدر.
4- الأحداث الجوهرية التي لها تأثير على الهيكل التمويلي للمصدر وقدرتها على سداد مستحقات حملة السندات وأي تأثير جوهري ضار على نشاط المصدر فور حدوث ذلك.
5- أي تعديلات قد تطرأ على موقف المصدر والسابق الإفصاح عنه بمذكرة المعلومات الخاصة بطرح السندات وذلك فور حدوثها.$b8_0$
