DO $verify193$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 145 AND law_year = 2021 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[193] القرار 145/2021 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 12 THEN RAISE EXCEPTION '[193] عدد المواد % بدل 12', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2026-07-08';
  IF v_v <> 12 THEN RAISE EXCEPTION '[193] عدد النسخ % بدل 12', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%اإلجارءات%' OR body LIKE '%الم ارفقة%' OR body LIKE '%قارارت%' OR body LIKE '%القارار%' OR body LIKE '%االكتتاب%' OR body LIKE '%اإلفصاح%' OR body LIKE '%اعتباارً%' OR body LIKE '%جملس%' OR body LIKE '%املالية%' OR body LIKE '%واخلاص%' OR body LIKE '%ا ً%' OR body LIKE '%ليادة%' OR body LIKE '%يجول%' OR body LIKE '%توليع%' OR body LIKE '%تجاول%' OR body LIKE '%رررر%' OR body LIKE '%الهيتة%' OR body LIKE '%القريةالذكية%' OR body LIKE '%FINANCIAL REGULATORY%' OR body LIKE '%WWW.FRA%' OR body LIKE '%رئيس الهيئة%' OR body LIKE '%اإلصدار%' OR body LIKE '%األوىل%' OR body LIKE '%تطأر%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[193] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على قانون شركات المساهمة%' AND body LIKE '%ر مجلس إدارة الهيئة رقم (23) لسنة 20%' AND body LIKE '%سته المنعقدة بتاريخ 2021/9/29؛' AND body LIKE '%رقم (159) لسنة 1981%' AND body LIKE '%رقم (11) لسنة 2014%' AND body LIKE '%رقم (48) لسنة 2019%' AND body LIKE '%بتاريخ 2021/9/29؛') THEN RAISE EXCEPTION '[193] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = -1 AND body LIKE 'تسري الضوابط والإجراءات المرافقة لهذ%' AND body LIKE '%وابط والإجراءات المرافقة لهذا القرار%' AND body LIKE '%يئة بشأن إصدار أو طرح السندات.' AND body LIKE '%وذلك مع عدم الإخلال بأي أحكام خاصة%') THEN RAISE EXCEPTION '[193] مادة الإصدار 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = -1 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية و%' AND body LIKE '% القرار في الوقائع المصرية وعلى المو%' AND body LIKE '% لتاريخ نشره بالوقائع المصرية.' AND body LIKE '%ويعمل به اعتبارًا من اليوم التالي%') THEN RAISE EXCEPTION '[193] مادة الإصدار 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE '1- الطرح العام: يتم الطرح العام للسن%' AND body LIKE '% الخاص: يتم الطرح الخاص للسندات بعرض%' AND body LIKE '% إصدار تلك السندات أو بعد ذلك.' AND body LIKE '%2- الطرح الخاص:%') THEN RAISE EXCEPTION '[193] القسم 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE '1- الشركة أو الجهة المصدرة (المصدر).%' AND body LIKE '% متلقية الاكتتاب.%' AND body LIKE '%(بالنسبة للسندات قصيرة الأجل).' AND body LIKE '%9- وكيل السداد%' AND body LIKE '%8- جهات التصنيف الائتماني%') THEN RAISE EXCEPTION '[193] القسم 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'يقصد بالمستثمر المؤهل للطرح الخاص، ا%' AND body LIKE '% التمويل العقاري أو إعادة التمويل ال%' AND body LIKE '%نها قرار من مجلس إدارة الهيئة.' AND body LIKE '%خمسمائة ألف جنيه%' AND body LIKE '%عن مليون جنيه مصري.%' AND body LIKE '%أكثر من 100 مليون جنيه.%' AND body LIKE '%19- صندوق مصر السيادي للاستثمار والتنمية.%' AND body LIKE '%20- صندوق مصر الفرعي للخدمات المالية والتحول الرقمي.%' AND body LIKE '%14- البنوك الأجنبية%' AND body LIKE '%ثلاث سنوات%') THEN RAISE EXCEPTION '[193] القسم 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE '1- يجب ألا تقل القيمة الاسمية للسند %' AND body LIKE '%إعادة شراء أو السداد المعجل للسندات %' AND body LIKE '%ترى الهيئة ضرورة موافاتها بها.' AND body LIKE '%عن مائة جنيه مصري%' AND body LIKE '%المادة (12) من قواعد قيد%' AND body LIKE '%للمادة (7) من اللائحة%' AND body LIKE '%(BBB-)%' AND body LIKE '%للمادة (34) من اللائحة%' AND body LIKE '%قبل تاريخ توزيع أول كوبون.%') THEN RAISE EXCEPTION '[193] القسم 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE '1- يكون الحد الأدنى للاكتتاب بالنسبة%' AND body LIKE '%م طرح السندات في طرح عام وطرح خاص فل%' AND body LIKE '% التوريق المحالة بحسب الأحوال.' AND body LIKE '%بنسبة (0.5_) من قيمة الطرح أو مليون جنيه%' AND body LIKE '%نسبة (1_) من قيمة الطرح أو 10 ملايين جنيه%' AND body LIKE '%بنسبة لا تقل عن (10_) من إجمالي%' AND body LIKE '%عن أسبوع ولا تجاوز ثلاثين يوم عمل%') THEN RAISE EXCEPTION '[193] القسم 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'يجب أن تتناول مذكرة المعلومات إقرار %' AND body LIKE '%اح عن أية معلومات جوهرية طارئة أو جد%' AND body LIKE '% المفصح عنها بمذكرة المعلومات.' AND body LIKE '%المادة (304) من اللائحة التنفيذية لقانون سوق رأس المال (4)%' AND body LIKE '%البند (1) من خامسًا%' AND body LIKE '%4- عدم الإدلاء%' AND body LIKE '%(ج) بيان الأشخاص%') THEN RAISE EXCEPTION '[193] القسم 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'يجب أن تتضمن مذكرة المعلومات البيانا%' AND body LIKE '%اح عن الغرض من الإصدار وأوجه استخدام%' AND body LIKE '%لتنفيذية لقانون سوق رأس المال.' AND body LIKE '%لنسبة (5_) فأكثر%' AND body LIKE '%11- تعهدات وإقرارات%' AND body LIKE '%(أ) القوائم المالية له%' AND body LIKE '%10- الإفصاح عن البيانات المالية%') THEN RAISE EXCEPTION '[193] القسم 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'مع عدم الإخلال بأي التزامات يتعين عل%' AND body LIKE '%من مراقب الحسابات يوضح كافة النسب ال%' AND body LIKE '% بطرح السندات وذلك فور حدوثها.' AND body LIKE '%خلال 90 يومًا%' AND body LIKE '%خلال 45 يومًا%' AND body LIKE '%5- أي تعديلات%') THEN RAISE EXCEPTION '[193] القسم 8 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE '(1) تم التعديل بموجب قرار مجلس إدارة%' AND body LIKE '%خاص: عرض أوراق مالية أو أدوات مالية %' AND body LIKE '%يئة رقم (136) بتاريخ 2026/7/8.' AND body LIKE '(1) تم التعديل بموجب قرار مجلس إدارة الهيئة رقم (136)%' AND body LIKE '%(3) تم استبدال نص الفقرة الثانية%' AND body LIKE '%(4) تم استبدال البند 2%' AND body LIKE '%الطرح الخاص: عرض أوراق مالية%') THEN RAISE EXCEPTION '[193] الهوامش غير سليم'; END IF;
  IF v_len <> 14223 THEN RAISE EXCEPTION '[193] إجمالى طول المواد % بدل 14223', v_len; END IF;
  RAISE NOTICE '[193] القرار 145/2021: 12 مواد و12 نسخ، إجمالى % حرف', v_len;
END
$verify193$;

COMMIT;
